package com.genisource.erp.production;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Finished goods that another order is going to make, as MRP sees them.
 *
 * <p>Only released orders count. An order that nobody has released has no material
 * committed to it, and would be regenerated by the next plan run anyway — counting it
 * would let a plan net a shortage against work that may never start.
 */
public record OpenSupplyLine(Long itemId,
                             BigDecimal qty,
                             LocalDate dueDate,
                             String docNo) {
}
